update public.institutions i set
  name = case when i.name is null then null else coalesce(d.j -> 'bySlug' -> i.slug -> 'name', '{}') || i.name end,
  description = case when i.description is null then null else coalesce(d.j -> 'bySlug' -> i.slug -> 'description', '{}') || i.description end,
  address = case when i.address is null then null else coalesce(d.j -> 'bySlug' -> i.slug -> 'address', '{}') || i.address end,
  languages = case when i.languages is null then null else coalesce(d.j -> 'phrases' -> 'languages' -> (i.languages ->> 'ru'), '{}') || i.languages end,
  study_form = case when i.study_form is null then null else coalesce(d.j -> 'phrases' -> 'study_form' -> (i.study_form ->> 'ru'), '{}') || i.study_form end
from d;
